( Tests of the Uxn CPU in uxn.fs )
\
\   lugforth examples/system/varvara/uxn_tests.fs
\
\ Each line is a ROM (hexadecimal) run from $0100 to its BRK, then either the
\ two stacks and a hash of the 64 KB of memory, or what it wrote to the
\ Console. The expected results come from uxn.wasm (an implementation that
\ passes the upstream opcode test suite), the first 100 for random
\ programs without jumps or devices, then one with the jumps, calls,
\ LDR/STR and keep mode, and one with the System device (stack pointers,
\ memory fill and copy), checked by hand.

needs uxn.fs
also uxn

: hexdig ( c -- n ) dup [char] 9 > if 7 - then [char] 0 - ;
: x" ( "hex" -- a n )
  [char] " parse here >r
  2/ 0 ?do dup i 2* + c@ hexdig 4 lshift over i 2* + 1+ c@ hexdig or c, loop
  drop r> here over - ;

create cout $100 allot
variable cout#
: capture-deo ( p -- ) $0f and 8 = if $18 dev@ cout cout# @ + c! 1 cout# +! then ;
: run ( a n -- ) load-bytes ['] plain-dei ['] capture-deo 1 device! 0 cout# ! $100 eval ;

: ram-hash ( -- h ) 0 $10000 0 do 31 * i ram + c@ + $ffffffff and loop ;
: stack= ( a n s -- f ) dup cell+ swap @ str= ;

variable passed  variable failed
: result ( f -- ) if 1 passed +! else 1 failed +! ." FAIL: test " passed @ failed @ + . cr then ;
: state ( rom n wst n rst n hash -- )
  { ra rn wa wn sa sn h }  ra rn run
  wa wn wst stack=  sa sn rst stack= and  ram-hash h = and  result ;
: output ( rom n out n -- ) 2swap run cout cout# @ str= result ;

